import fs from 'node:fs';
import vm from 'node:vm';
const source=fs.readFileSync('index.html','utf8');
const code=source.slice(source.indexOf('function createVisionAdapter('),source.indexOf('\nfunction createHarness()')).replace('await import(m.assets.library)','await Promise.resolve(injectedVision)');
const options=[];const canvases=[];
const make=async(files,opt)=>{options.push(opt);return {close(){}};};
const context={injectedVision:{FilesetResolver:{forVisionTasks:async()=>({})},FaceLandmarker:{createFromOptions:make},HandLandmarker:{createFromOptions:make}},Uint8Array,sha256Hex:()=> 'hash'};
vm.createContext(context);vm.runInContext(code,context);
const view={fetch:async()=>({ok:true,arrayBuffer:async()=>new ArrayBuffer(0)}),document:{createElement:()=>{const c={getContext:()=>({})};canvases.push(c);return c;}}};
const adapter=context.createVisionAdapter(view);
const events=[];adapter.onmessage=e=>events.push(e.data);
adapter.postMessage({type:'load',assets:{faceSha256:'hash',handSha256:'hash'}});
await new Promise(resolve=>setImmediate(resolve));
const checks=[{name:'both tasks receive an explicit canvas',passed:options.length===2&&options.every(o=>!!o.canvas)},{name:'face and hand use distinct canvases',passed:options.length===2&&options[0].canvas!==options[1].canvas}];
adapter.terminate();
let fetches=0;
const blocked=context.createVisionAdapter({document:{createElement:()=>({getContext:()=>null})},fetch:async()=>{fetches++;throw Error('network should not run');}});
const errors=[];blocked.onmessage=e=>errors.push(e.data);
blocked.postMessage({type:'load',assets:{}});
await new Promise(resolve=>setImmediate(resolve));
checks.push({name:'unsupported graphics fails before downloads',passed:fetches===0});
checks.push({name:'unsupported graphics reports explicit WebGL requirement',passed:errors.some(e=>e.type==='error'&&e.message.includes('WebGL is unavailable'))});
blocked.terminate();
const result={passed:checks.filter(c=>c.passed).length,failed:checks.filter(c=>!c.passed).length,checks};console.log(JSON.stringify(result,null,2));process.exitCode=result.failed?1:0;
